const events=[{id:'afterglow',name:'Afterglow',poster:'After\nhours.\nAll in.',city:'Visakhapatnam',date:'OCT 10, 2026',time:'7 PM onwards',venue:'Seafront venue · To be announced',genre:'HOUSE / ELECTRONIC',description:'A sunset that turns into a soundtrack. Deep grooves, sea air, and your kind of people.',price:799,vip:1499,color:''},{id:'soft-signal',name:'Soft Signal',poster:'Soft\nsignal.\nLoud souls.',city:'Hyderabad',date:'OCT 24, 2026',time:'8 PM onwards',venue:'City venue · To be announced',genre:'INDIE / ALTERNATIVE',description:'For the songs you know by heart and the people you are about to meet.',price:699,vip:1299,color:'coral'},{id:'nocturne',name:'Nocturne',poster:'Lose\ntrack.\nFind us.',city:'Bengaluru',date:'NOV 07, 2026',time:'8 PM onwards',venue:'City venue · To be announced',genre:'TECHNO / AFTER DARK',description:'Step out of the everyday. An after-dark journey through sound and connection.',price:999,vip:1799,color:'blue'}];
const money=n=>'₹'+n.toLocaleString('en-IN');
function poster(e){return `<div class="event-art ${e.color}"><div class="poster-top"><span>THE LUCID SWAY PRESENTS</span><span>✳</span></div><div class="poster-name">${e.poster.replaceAll('\n','<br>')}</div><div class="poster-bottom"><span>${e.genre}</span><span>↗</span></div></div>`}
function renderEvents(){const city=document.querySelector('#city').value;document.querySelector('#event-grid').innerHTML=events.filter(e=>city==='All cities'||e.city===city).map((e,i)=>`<article class="event-card" style="animation-delay:${i*80}ms">${poster(e)}<div class="event-meta"><span>${e.date}</span><span>${e.city}</span></div><h3>${e.name}</h3><p>${e.description}</p><div class="card-bottom"><span>From ${money(e.price)}</span><a class="booking-link" href="/events/${e.id}/">Explore event ↗</a></div></article>`).join('');}
renderEvents();document.querySelector('#city').addEventListener('change',renderEvents);
const dialog=document.querySelector('#event-dialog');let returnFocus;
function showEvent(id,standalone=false){const e=events.find(e=>e.id===id);if(!e)return;returnFocus=document.activeElement;document.querySelector('#event-content').innerHTML=`<button class="close" aria-label="Close event">×</button><span class="eyebrow">YOUR NIGHT, SORTED / UI PREVIEW</span><div class="detail-grid"><div class="detail-info">${poster(e)}<h2 id="event-title" style="margin-top:22px">${e.name}</h2><p>${e.description}</p><p><b>${e.date} · ${e.time}</b><br>${e.city}<br>${e.venue}</p><p class="form-note">Illustrative event. Venue and map will be added when confirmed.</p></div><form class="booking-form"><label>Your pass<select name="pass"><option value="${e.price}">Standard · ${money(e.price)}</option><option value="${e.vip}">VIP · ${money(e.vip)}</option></select></label><label>Full name<input name="name" autocomplete="name" required maxlength="100" placeholder="Your name"></label><label>WhatsApp number<input name="phone" type="tel" autocomplete="tel" required pattern="[+0-9 ()-]{10,18}" placeholder="+91 98765 43210"></label><label>Email address<input name="email" type="email" autocomplete="email" required placeholder="you@example.com"></label><div class="form-row"><label>Promo code<input name="promo" placeholder="Try EARLYBIRD"></label><label>Referral (optional)<input name="referral" placeholder="Code or name"></label></div><span class="form-note" id="promo-message" aria-live="polite">Demo: EARLYBIRD gives 10% off.</span><div class="total"><span>Total</span><strong id="total">${money(e.price)}</strong></div><button type="submit" class="button dark">Preview reservation <span>↗</span></button><span class="form-note">Demo only. No payment is taken and no registration is saved or sent.</span></form></div>`;if(!standalone){if(!dialog.open)dialog.showModal();document.body.style.overflow='hidden'}const form=document.querySelector('#event-content form');const update=()=>{const promo=form.elements.promo.value.trim().toUpperCase(),discount=promo==='EARLYBIRD';document.querySelector('#total').textContent=money(Math.round(Number(form.elements.pass.value)*(discount?.9:1)));document.querySelector('#promo-message').textContent=discount?'EARLYBIRD applied · 10% off':promo?'This demo code is not available. Try EARLYBIRD.':'Demo: EARLYBIRD gives 10% off.'};form.elements.pass.addEventListener('change',update);form.elements.promo.addEventListener('input',update);form.addEventListener('submit',ev=>{ev.preventDefault();const total=document.querySelector('#total').textContent;document.querySelector('#event-content').innerHTML=`<button class="close" aria-label="Close preview">×</button><div class="success"><div class="success-icon">✳</div><span class="eyebrow">RESERVATION PREVIEW</span><h2 id="event-title">A good night is calling.</h2><p>${e.name} · ${e.city}<br>${e.date} · ${e.time}<br>Selected pass total: <b>${total}</b></p><p>This is the confirmation design preview.<br>No booking, payment, or valid entry ticket has been created.</p><button class="button dark" id="done">Back to the nights ↗</button></div>`;document.querySelector('#done').focus()});}
document.addEventListener('click',e=>{const event=e.target.closest('[data-event]');if(event)location.hash='event/'+event.dataset.event;if(e.target.closest('.close,#done')){const parent=e.target.closest('dialog');if(parent)parent.close();else if(e.target.closest('#done'))location.href='/#events'}});
function route(){const id=location.hash.match(/^#event\/(.+)$/)?.[1];if(id&&events.some(e=>e.id===id))location.replace('/events/'+id+'/');else if(dialog.open)dialog.close()}
window.addEventListener('hashchange',route);route();dialog.addEventListener('close',()=>{document.body.style.overflow='';if(location.hash.startsWith('#event/'))history.replaceState(null,'','#events');returnFocus?.focus()});
const gallery=document.querySelector('#gallery-dialog');gallery.addEventListener('close',()=>document.body.style.overflow='');for(const d of [dialog,gallery])d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});
const motion=document.querySelector('#motion-toggle');motion.onclick=()=>{const paused=document.body.classList.toggle('motion-off');motion.setAttribute('aria-pressed',String(paused));motion.setAttribute('aria-label',paused?'Enable animations':'Pause animations');motion.querySelector('span').textContent=paused?'▷':'Ⅱ'};
function updateClock(){document.querySelector('#clock').textContent=new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})}updateClock();setInterval(updateClock,60000);
